"""Records the audio samples of the volume falloff of the CreateListener wiki page: a 440 Hz tone that moves away from the listener
(from 1 to 61 meters in two seconds, doppler off), with the falloff of this runtime and with the ones of SoLoud and of the
original (BLITZLLVM_VOLUME_FALLOFF=soloud and =legacy), as mono 16 bit files of 11025 Hz. Prints the gain over the distance as well.

Usage: render_falloff_samples.py <blitzcc> <output folder>
"""
import math
import os
import struct
import sys
import tempfile
import wave
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "."))
import procutil  # noqa: E402

blitzcc, out_dir = (os.path.abspath(a) for a in sys.argv[1:3])
os.makedirs(out_dir, exist_ok=True)
work = tempfile.mkdtemp()
os.chdir(work)

CYCLE, RATE = 50, 22050
with wave.open("tone.wav", "wb") as f:
	f.setnchannels(1)
	f.setsampwidth(2)
	f.setframerate(RATE)
	f.writeframes(b"".join(struct.pack("<h", int(9000 * math.sin(2 * math.pi * i / CYCLE))) for i in range(CYCLE * 40)))

SOURCE = """
s = Load3DSound("tone.wav")
LoopSound s
listener = CreatePivot()
source = CreatePivot()
PositionEntity source, 0, 0, 1
CreateListener listener, 1, 0, 1
c = EmitSound(s, source)
Delay 300
For i = 1 To 40
	MoveEntity source, 0, 0, 1.5
	Delay 50
Next
"""


def record(name, model):
	with open("play.bb", "w") as f:
		f.write(SOURCE)
	procutil.run([blitzcc, "play.bb", "-o", "play"], check=True, capture_output=True)
	if os.path.exists("sdlaudio.raw"):
		os.remove("sdlaudio.raw")
	env = dict(os.environ, SDL_AUDIODRIVER="disk", SDL_DISKAUDIODELAY="0")
	env.pop("BLITZ_HEADLESS", None)
	env.pop("BLITZLLVM_VOLUME_FALLOFF", None)
	if model != "new":
		env["BLITZLLVM_VOLUME_FALLOFF"] = model
	procutil.run(["./play"], env=env, capture_output=True, timeout=60)
	data = open("sdlaudio.raw", "rb").read()
	count = len(data) // 4
	left = struct.unpack("<%dh" % (count * 2), data[: count * 4])[0::2]
	loud = [i for i, v in enumerate(left) if abs(v) > 100]
	chosen = left[loud[0] : loud[-1] + 1 : 4]
	with wave.open(os.path.join(out_dir, name), "wb") as f:
		f.setnchannels(1)
		f.setsampwidth(2)
		f.setframerate(11025)
		f.writeframes(struct.pack("<%dh" % len(chosen), *chosen))
	peaks = [max(abs(v) for v in chosen[i : i + 11025 // 4]) for i in range(0, len(chosen) - 11025 // 4, 11025 // 4)]
	print(name, "peak per quarter second:", peaks)


record("falloff_new.wav", "new")
record("falloff_soloud.wav", "soloud")
record("falloff_legacy.wav", "legacy")
